/* admin-studio.html inline style block 1 (from line 35) */
body.admin-access-pending,
        body.admin-access-denied {
            overflow: hidden;
        }

        body.admin-access-pending .admin-layout {
            visibility: hidden;
            pointer-events: none;
        }

        body.admin-access-denied .admin-layout {
            display: none;
        }

        .admin-access-screen {
            position: fixed;
            inset: 0;
            z-index: 99999;
            display: none;
            align-items: center;
            justify-content: center;
            padding: 24px;
            background:
                radial-gradient(circle at top, rgba(90, 126, 214, 0.2), transparent 45%),
                linear-gradient(180deg, rgba(10, 14, 26, 0.98), rgba(8, 10, 18, 0.99));
        }

        body.admin-access-pending .admin-access-screen,
        body.admin-access-denied .admin-access-screen {
            display: flex;
        }

        .admin-access-card {
            width: min(100%, 520px);
            padding: 36px 32px;
            border-radius: 24px;
            border: 1px solid rgba(255, 255, 255, 0.08);
            background: rgba(14, 19, 34, 0.9);
            box-shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
            text-align: center;
            color: #f3f4f6;
        }

        .admin-access-icon {
            width: 68px;
            height: 68px;
            margin: 0 auto 18px;
            border-radius: 50%;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            background: rgba(107, 158, 206, 0.14);
            color: #9ec5ff;
            font-size: 28px;
        }

        body.admin-access-denied .admin-access-icon {
            background: rgba(248, 113, 113, 0.14);
            color: #fca5a5;
        }

        .admin-access-title {
            margin: 0 0 12px;
            font-size: 30px;
            line-height: 1.15;
            font-family: "Playfair Display", serif;
        }

        .admin-access-message {
            margin: 0;
            color: rgba(243, 244, 246, 0.76);
            font-size: 15px;
            line-height: 1.7;
        }

        /* 20260426_ADMIN_STUDIO_ACCESS_DOTS_HOME_LOGO_1 */
        .admin-access-spinner {
            margin: 28px auto 0;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            color: #9ec5ff;
        }

        .admin-access-spinner span {
            width: 9px;
            height: 9px;
            border-radius: 999px;
            background: currentColor;
            opacity: 0.24;
            animation: admin-access-pending-dots 1.05s ease-in-out infinite;
        }

        .admin-access-spinner span:nth-child(2) {
            animation-delay: 0.16s;
        }

        .admin-access-spinner span:nth-child(3) {
            animation-delay: 0.32s;
        }

        /* 20260426_ADMIN_STUDIO_LOADING_DOTS_BRIDGE_1 */
        .admin-module-loading-host {
            width: 100%;
            display: flex !important;
            align-items: center !important;
            justify-content: center !important;
            margin-inline: auto;
            text-align: center !important;
            color: #8fb8e5 !important;
            background: transparent !important;
            background-image: none !important;
            border: 0 !important;
            box-shadow: none !important;
            text-shadow: none !important;
            filter: none !important;
            backdrop-filter: none !important;
            -webkit-backdrop-filter: none !important;
        }

        .admin-module-loading-host[hidden] {
            display: none !important;
        }

        .admin-module-loading-host--block,
        .admin-module-loading-host--hero {
            padding: 24px 0 !important;
        }

        .admin-module-loading-host--inline {
            width: auto;
            display: inline-flex !important;
            min-height: 0 !important;
            padding: 0 !important;
        }

        .admin-module-loading-host--cell {
            min-height: 0 !important;
            padding: 20px 12px !important;
        }

        .admin-module-loading-host.loading-text {
            color: #8fb8e5 !important;
            font-size: inherit !important;
            overflow: visible;
        }

        .admin-module-loading-host.loading-text::before,
        .admin-module-loading-host.loading-text::after {
            content: none !important;
            display: none !important;
            animation: none !important;
        }

        .admin-module-loading-dots {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            flex-shrink: 0;
        }

        .admin-module-loading-dots span {
            width: 8px;
            height: 8px;
            border-radius: 999px;
            background: currentColor;
            opacity: 0.24;
            animation: admin-module-loading-dots 1.05s ease-in-out infinite;
        }

        .admin-module-loading-dots span:nth-child(2) {
            animation-delay: 0.16s;
        }

        .admin-module-loading-dots span:nth-child(3) {
            animation-delay: 0.32s;
        }

        .admin-module-loading-dots--inline {
            gap: 5px;
        }

        .admin-module-loading-dots--inline span {
            width: 6px;
            height: 6px;
        }

        .admin-module-loading-dots--cell {
            gap: 6px;
        }

        .admin-module-loading-dots--cell span {
            width: 7px;
            height: 7px;
        }

        .admin-module-loading-dots--hero {
            gap: 10px;
        }

        .admin-module-loading-dots--hero span {
            width: 10px;
            height: 10px;
        }

        .admin-access-actions {
            display: none;
            justify-content: center;
            gap: 12px;
            margin-top: 24px;
            flex-wrap: wrap;
        }

        body.admin-access-denied .admin-access-actions {
            display: flex;
        }

        body.admin-access-denied .admin-access-spinner {
            display: none;
        }

        .admin-access-btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            min-width: 140px;
            padding: 12px 18px;
            border-radius: 999px;
            border: 1px solid rgba(255, 255, 255, 0.12);
            color: #f9fafb;
            text-decoration: none;
            background: rgba(255, 255, 255, 0.04);
            transition: transform 0.2s ease, background 0.2s ease, border-color 0.2s ease;
        }

        .admin-access-btn:hover {
            transform: translateY(-1px);
            background: rgba(255, 255, 255, 0.08);
            border-color: rgba(255, 255, 255, 0.2);
        }

        .admin-access-btn.primary {
            background: linear-gradient(135deg, #5f8cff, #3b82f6);
            border-color: rgba(159, 195, 255, 0.6);
        }

        @keyframes admin-access-pending-dots {
            0%, 80%, 100% {
                transform: translateY(0);
                opacity: 0.24;
            }

            40% {
                transform: translateY(-3px);
                opacity: 0.96;
            }
        }

        @keyframes admin-module-loading-dots {
            0%, 80%, 100% {
                transform: translateY(0);
                opacity: 0.24;
            }

            40% {
                transform: translateY(-3px);
                opacity: 0.96;
            }
        }

        .sidebar-brand-icon {
            width: 30px;
            height: 30px;
        }

        .sidebar-brand-logo {
            width: 30px;
            height: 30px;
            display: block;
        }


/* admin-studio.html inline style block 2 (from line 299) */
.admin-site-selector {
                    position: relative;
                    display: inline-flex;
                    flex-shrink: 0;
                }

                /* 20260427_ADMIN_STUDIO_HEADER_THEME_TOGGLE_1 */
                /* 20260427_ADMIN_STUDIO_SITE_SWITCHER_POLISH_1 */
                /* 20260427_ADMIN_SITE_SWITCHER_NO_HOVER_LIFT_1 */
                .admin-site-filter-toolbar {
                    display: flex;
                    align-items: center;
                    gap: 10px;
                }

                .admin-site-filter-toolbar .admin-site-selector {
                    flex-shrink: 0;
                }

                .admin-theme-toggle-btn {
                    flex-shrink: 0;
                    width: 42px;
                    height: 42px;
                    border-radius: 14px;
                    border: 1px solid rgba(148, 163, 184, 0.18);
                    background: rgba(255, 255, 255, 0.04);
                    color: var(--text-dim, #94a3b8);
                    box-shadow: 0 14px 32px rgba(15, 23, 42, 0.12);
                }

                .admin-theme-toggle-btn::after {
                    border-radius: inherit;
                }

                .admin-theme-toggle-btn:hover,
                .admin-theme-toggle-btn:focus-visible {
                    transform: none;
                    background: rgba(255, 255, 255, 0.08);
                    border-color: rgba(125, 211, 252, 0.24);
                    box-shadow: 0 16px 34px rgba(15, 23, 42, 0.16);
                }

                .admin-theme-toggle-btn:focus-visible {
                    outline: none;
                }

                .site-selector-btn,
                .site-selector-option {
                    appearance: none;
                    -webkit-appearance: none;
                    border: 0;
                    font-family: var(--font-sans, inherit);
                }

                .site-selector-btn {
                    min-width: 142px;
                    height: 42px;
                    display: inline-flex;
                    align-items: center;
                    gap: 10px;
                    padding: 5px 8px 5px 6px;
                    border-radius: 14px;
                    background: rgba(15, 23, 42, 0.42);
                    border: 1px solid rgba(148, 163, 184, 0.2);
                    color: rgba(241, 245, 249, 0.94);
                    cursor: pointer;
                    font-size: 13px;
                    line-height: 1;
                    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
                    transition: background 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
                }

                .site-selector-btn:hover,
                .admin-site-selector.is-open .site-selector-btn {
                    transform: none;
                    background: rgba(30, 41, 59, 0.68);
                    border-color: rgba(125, 211, 252, 0.28);
                    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
                }

                .site-selector-btn:focus-visible {
                    transform: none;
                    outline: none;
                    border-color: rgba(96, 165, 250, 0.5);
                    box-shadow: 0 0 0 3px rgba(96, 165, 250, 0.18), inset 0 1px 0 rgba(255, 255, 255, 0.08);
                }

                .site-selector-btn__mark,
                .site-selector-option__mark {
                    flex: 0 0 auto;
                    display: inline-flex;
                    align-items: center;
                    justify-content: center;
                    border-radius: 10px;
                    color: #dbeafe;
                    background: rgba(96, 165, 250, 0.16);
                }

                .site-selector-btn__mark {
                    width: 30px;
                    height: 30px;
                    font-size: 13px;
                }

                .site-selector-btn__mark--all,
                .site-selector-option__mark--all {
                    color: #bae6fd;
                    background: rgba(14, 165, 233, 0.14);
                }

                .site-selector-btn__mark--cn,
                .site-selector-option__mark--cn {
                    color: #bfdbfe;
                    background: rgba(96, 165, 250, 0.18);
                }

                .site-selector-btn__mark--intl,
                .site-selector-option__mark--intl {
                    color: #c7d2fe;
                    background: rgba(129, 140, 248, 0.18);
                }

                .site-selector-btn__copy {
                    min-width: 0;
                    display: flex;
                    flex-direction: column;
                    align-items: flex-start;
                    justify-content: center;
                }

                .site-selector-option__copy {
                    min-width: 0;
                    display: flex;
                    flex-direction: column;
                    align-items: flex-start;
                }

                .site-selector-kicker {
                    font-size: 10px;
                    font-weight: 600;
                    line-height: 1.1;
                    color: rgba(148, 163, 184, 0.82);
                }

                .site-selector-label {
                    max-width: 70px;
                    overflow: hidden;
                    text-overflow: ellipsis;
                    white-space: nowrap;
                    font-size: 14px;
                    font-weight: 700;
                    line-height: 1.25;
                    color: currentColor;
                }

                .site-selector-chevron {
                    margin-left: auto;
                    display: inline-flex;
                    align-items: center;
                    justify-content: center;
                    width: 22px;
                    height: 22px;
                    border-radius: 8px;
                    color: rgba(148, 163, 184, 0.86);
                    transition: transform 0.18s ease, color 0.18s ease, background 0.18s ease;
                }

                .site-selector-chevron i {
                    font-size: 10px;
                }

                .admin-site-selector.is-open .site-selector-chevron {
                    transform: rotate(180deg);
                    color: rgba(226, 232, 240, 0.94);
                    background: rgba(255, 255, 255, 0.07);
                }

                .site-selector-menu {
                    position: absolute;
                    top: calc(100% + 8px);
                    right: 0;
                    display: grid;
                    gap: 4px;
                    width: 210px;
                    padding: 6px;
                    background: rgba(15, 23, 42, 0.92);
                    border: 1px solid rgba(148, 163, 184, 0.16);
                    border-radius: 14px;
                    z-index: 999;
                    box-shadow: 0 22px 54px rgba(2, 8, 23, 0.38), inset 0 1px 0 rgba(255, 255, 255, 0.04);
                    opacity: 0;
                    pointer-events: none;
                    transform: translateY(-4px) scale(0.98);
                    transform-origin: top right;
                    transition: opacity 0.16s ease, transform 0.16s ease, visibility 0.16s ease;
                    visibility: hidden;
                    backdrop-filter: blur(18px) saturate(120%);
                    -webkit-backdrop-filter: blur(18px) saturate(120%);
                }

                .site-selector-menu.show {
                    opacity: 1;
                    pointer-events: auto;
                    transform: translateY(0) scale(1);
                    visibility: visible;
                }

                .site-selector-option {
                    width: 100%;
                    min-height: 48px;
                    display: flex;
                    align-items: center;
                    gap: 10px;
                    padding: 7px 8px;
                    box-sizing: border-box;
                    border: 1px solid transparent;
                    border-radius: 10px;
                    cursor: pointer;
                    font-size: 13px;
                    color: rgba(226, 232, 240, 0.86);
                    background: transparent;
                    text-align: left;
                    transition: background 0.15s ease, color 0.15s ease, transform 0.15s ease;
                }

                /* 20260427_ADMIN_SITE_SWITCHER_ACTIVE_HOVER_LOCK_1 */
                .site-selector-option:not(.active):hover,
                .site-selector-option:not(.active):focus-visible {
                    background: rgba(148, 163, 184, 0.12);
                    color: #f8fafc;
                    outline: none;
                }

                .site-selector-option.active {
                    background: rgba(107, 158, 206, 0.18);
                    color: #f8fbff;
                    font-weight: 600;
                }

                .site-selector-option__mark {
                    width: 32px;
                    height: 32px;
                    font-size: 13px;
                }

                .site-selector-option__label {
                    font-size: 13px;
                    font-weight: 700;
                    line-height: 1.15;
                }

                .site-selector-option__hint {
                    margin-top: 3px;
                    font-size: 11px;
                    line-height: 1.15;
                    color: rgba(148, 163, 184, 0.82);
                }

                .site-selector-option__check {
                    margin-left: auto;
                    width: 20px;
                    height: 20px;
                    display: inline-flex;
                    align-items: center;
                    justify-content: center;
                    border-radius: 999px;
                    color: #93c5fd;
                    background: rgba(96, 165, 250, 0.12);
                    opacity: 0;
                    transform: scale(0.82);
                    transition: opacity 0.15s ease, transform 0.15s ease;
                }

                .site-selector-option__check i {
                    font-size: 10px;
                }

                .site-selector-option.active .site-selector-option__check {
                    opacity: 1;
                    transform: scale(1);
                }

                html[data-theme="light"] .admin-theme-toggle-btn,
                html:not([data-theme="dark"]) .admin-theme-toggle-btn {
                    background: rgba(255, 255, 255, 0.82);
                    border-color: rgba(15, 23, 42, 0.08);
                    color: rgba(51, 65, 85, 0.78);
                    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.02);
                }

                html[data-theme="light"] .admin-theme-toggle-btn:hover,
                html[data-theme="light"] .admin-theme-toggle-btn:focus-visible,
                html:not([data-theme="dark"]) .admin-theme-toggle-btn:hover,
                html:not([data-theme="dark"]) .admin-theme-toggle-btn:focus-visible {
                    transform: none;
                    background: #ffffff;
                    border-color: rgba(118, 157, 202, 0.18);
                    color: #0f172a;
                    box-shadow: 0 10px 26px rgba(15, 23, 42, 0.08);
                }

                html[data-theme="light"] .site-selector-btn,
                html:not([data-theme="dark"]) .site-selector-btn {
                    background: rgba(248, 251, 255, 0.96);
                    border-color: rgba(87, 124, 172, 0.26);
                    color: #111827;
                    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.92);
                }

                html[data-theme="light"] .site-selector-btn:hover,
                html[data-theme="light"] .admin-site-selector.is-open .site-selector-btn,
                html:not([data-theme="dark"]) .site-selector-btn:hover,
                html:not([data-theme="dark"]) .admin-site-selector.is-open .site-selector-btn {
                    transform: none;
                    background: #ffffff;
                    border-color: rgba(59, 112, 184, 0.36);
                    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.96);
                }

                html[data-theme="light"] .site-selector-btn:focus-visible,
                html:not([data-theme="dark"]) .site-selector-btn:focus-visible {
                    transform: none;
                    border-color: rgba(59, 112, 184, 0.38);
                    box-shadow: 0 0 0 3px rgba(59, 112, 184, 0.14), inset 0 1px 0 rgba(255, 255, 255, 0.96);
                }

                html[data-theme="light"] .site-selector-btn__mark,
                html:not([data-theme="dark"]) .site-selector-btn__mark {
                    color: #2d5fba;
                    background: #cfe1fb;
                }

                html[data-theme="light"] .site-selector-btn__mark--all,
                html:not([data-theme="dark"]) .site-selector-btn__mark--all {
                    color: #087ba5;
                    background: #cdeeff;
                }

                html[data-theme="light"] .site-selector-btn__mark--intl,
                html:not([data-theme="dark"]) .site-selector-btn__mark--intl {
                    color: #5146b8;
                    background: #dadcff;
                }

                html[data-theme="light"] .site-selector-kicker,
                html:not([data-theme="dark"]) .site-selector-kicker {
                    color: rgba(71, 85, 105, 0.88);
                }

                html[data-theme="light"] .site-selector-chevron,
