                html[data-theme="light"] .admin-site-selector.is-open .site-selector-chevron,
                html:not([data-theme="dark"]) .admin-site-selector.is-open .site-selector-chevron {
                    color: #0f172a;
                    background: rgba(59, 112, 184, 0.12);
                }

                html[data-theme="light"] .site-selector-menu,
                html:not([data-theme="dark"]) .site-selector-menu {
                    background: rgba(255, 255, 255, 0.98) !important;
                    border-color: rgba(87, 124, 172, 0.2) !important;
