                        /* Import View - Starry Blue Theme */
                        .import-panel {
                            background: rgba(15, 23, 42, 0.6);
                            border: 1px solid rgba(255, 255, 255, 0.08);
                            border-radius: 20px;
                            padding: 40px;
                            backdrop-filter: blur(24px);
                            box-shadow: 0 30px 60px rgba(0, 0, 0, 0.4),
                                inset 0 0 0 1px rgba(255, 255, 255, 0.05);
                            max-width: 900px;
                            margin: 40px auto;
                            position: relative;
                            overflow: hidden;
                        }

                        /* Decorative glowing orb effect */
                        .import-panel::before {
                            content: '';
                            position: absolute;
                            top: -100px;
                            left: -100px;
                            width: 300px;
                            height: 300px;
                            background: radial-gradient(circle, rgba(107, 158, 206, 0.15) 0%, transparent 70%);
                            border-radius: 50%;
                            pointer-events: none;
