                        .import-panel-header {
                            display: flex;
                            align-items: center;
                            gap: 15px;
                            margin-bottom: 30px;
                            border-bottom: 1px solid rgba(255, 255, 255, 0.08);
                            padding-bottom: 20px;
                        }

                        .import-panel-title {
                            font-size: 20px;
                            font-weight: 600;
                            color: #fff;
                            text-shadow: 0 2px 4px rgba(0, 0, 0, 0.3);
                        }

                        .glass-label {
                            display: block;
                            color: rgba(148, 163, 184, 1);
                            font-size: 14px;
                            margin-bottom: 10px;
                            font-weight: 500;
                            letter-spacing: 0.02em;
                        }

                        .glass-input {
                            width: 100%;
                            background: rgba(30, 41, 59, 0.4);
                            border: 1px solid rgba(255, 255, 255, 0.08);
                            border-radius: 12px;
                            padding: 16px;
                            color: #fff;
                            font-size: 15px;
                            outline: none;
                            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
                            box-sizing: border-box;
                        }

                        .glass-input:focus {
                            background: rgba(30, 41, 59, 0.6);
                            border-color: #6b9ece;
                            box-shadow: 0 0 0 4px rgba(107, 158, 206, 0.15);
                        }

                        .glass-input option {
                            background: #1e293b;
                            color: #fff;
                        }

                        /* Status Cards */
                        .status-options {
                            display: grid;
                            grid-template-columns: 1fr 1fr;
                            gap: 20px;
                        }

                        .status-card {
                            position: relative;
                            cursor: pointer;
                        }

                        .status-card-content {
                            background: rgba(30, 41, 59, 0.4);
                            border: 1px solid rgba(255, 255, 255, 0.08);
                            border-radius: 12px;
                            padding: 20px;
                            display: flex;
                            align-items: center;
                            gap: 15px;
                            transition: all 0.3s;
                        }

                        .status-card input:checked+.status-card-content {
                            background: rgba(107, 158, 206, 0.08);
                            border-color: #6b9ece;
                        }

