                        /* Import Button */
                        .btn-glow {
                            background: #6b9ece;
                            border: none;
                            border-radius: 12px;
                            padding: 16px 48px;
                            color: white;
                            font-weight: 600;
                            font-size: 16px;
                            cursor: pointer;
                            transition: all 0.3s;
                            box-shadow: 0 10px 20px rgba(59, 130, 246, 0.3);
                            display: flex;
                            align-items: center;
                            gap: 12px;
                        }

                        .btn-glow:hover {
                            transform: translateY(-2px) scale(1.02);
                            box-shadow: 0 20px 40px rgba(59, 130, 246, 0.5);
                            filter: brightness(1.1);
                        }

                        .import-textarea {
                            resize: vertical;
                            font-family: 'Monaco', 'Consolas', monospace;
                            line-height: 1.6;
                        }

                        /* Import 2-Column Layout */
                        .import-layout {
                            display: grid;
                            grid-template-columns: 280px 1fr;
                            gap: 20px;
                            max-width: 1200px;
                            margin: 20px auto;
                            height: 750px;
                            padding: 0 20px;
                            box-sizing: border-box;
                        }

                        /* Mobile Import Layout */
                        @media (max-width: 768px) {
                            .import-layout {
                                grid-template-columns: 1fr;
                                height: auto;
                                gap: 0;
                                padding: 0 10px;
                                margin: 10px auto;
                            }

                            .import-sidebar {
                                border-radius: 16px 16px 0 0;
                                max-height: 300px;
                                min-height: 200px;
                            }

                            .import-main {
                                border-radius: 0 0 16px 16px;
                                border-top: none;
                                min-height: 400px;
                            }

                            /* Hide sidebar by default on mobile, show via toggle */
