                            transition: background 0.15s;
                            user-select: none;
                            -webkit-user-select: none;
                            -webkit-touch-callout: none;
                            touch-action: manipulation;
                            position: relative;
                        }

                        .tree-category--dragging {
                            opacity: 0.42;
                        }

                        .tree-category-handle {
                            width: 24px;
                            height: 24px;
                            margin-right: 4px;
                            border: none;
                            border-radius: 6px;
                            background: transparent;
                            color: rgba(255, 255, 255, 0.24);
                            cursor: grab;
                            display: inline-flex;
                            align-items: center;
                            justify-content: center;
                            flex-shrink: 0;
                            padding: 0;
                            transition: color 0.15s ease, background 0.15s ease;
                        }

                        .tree-category-handle:hover {
                            color: rgba(255, 255, 255, 0.6);
                            background: rgba(255, 255, 255, 0.05);
                        }

                        .tree-category-handle:active {
                            cursor: grabbing;
                        }

                        .tree-category-header:hover {
                            background: rgba(255, 255, 255, 0.05);
                        }

                        .tree-category-header.active {
                            background: rgba(107, 158, 206, 0.1);
                        }

                        .tree-chevron {
                            width: 16px;
                            font-size: 10px;
                            color: rgba(255, 255, 255, 0.4);
                            transition: transform 0.2s ease;
                            margin-right: 6px;
                        }

                        .tree-category.expanded .tree-chevron {
                            transform: rotate(90deg);
                        }

                        .tree-folder-icon {
                            font-size: 16px;
                            color: rgba(255, 255, 255, 0.5);
                            margin-right: 10px;
                        }

                        .tree-folder-icon--recycle-bin {
                            color: #ef4444;
                        }

                        .tree-category.expanded .tree-folder-icon:not([class*="category-color--"]) {
                            color: #6b9ece;
                        }

                        .tree-category-name {
                            flex: 1;
                            min-width: 0;
                            font-size: 16px;
                            font-weight: 500;
                            color: rgba(255, 255, 255, 0.85);
                        }

                        .tree-category-name--muted {
                            color: rgba(255, 255, 255, 0.5);
                        }

                        .tree-category-count {
                            font-size: 13px;
                            color: rgba(255, 255, 255, 0.4);
                            padding: 3px 10px;
                            background: rgba(255, 255, 255, 0.05);
                            border-radius: 10px;
                            user-select: none;
                            -webkit-user-select: none;
                            -webkit-touch-callout: none;
                        }

                        .tree-category-count--danger {
                            background: rgba(239, 68, 68, 0.2);
                            color: #ef4444;
                        }

                        /* Product Children (Indented) */
                        .tree-children {
                            display: none;
                            padding-left: 42px;
                        }

                        .tree-category.expanded .tree-children {
                            display: block;
                        }

                        .tree-product-item {
                            display: flex;
                            align-items: center;
                            padding: 8px 15px 8px 10px;
                            margin: 2px 10px 2px 0;
                            border-radius: 6px;
                            cursor: pointer;
                            transition: all 0.15s;
