.codes-modal--batch :is(
    .points-batch-codes-action-btn,
    .points-batch-codes-toolbar-btn,
    .points-batch-codes-row-btn,
    .points-batch-codes-select-trigger,
    .points-batch-codes-select-option,
    .modal-close-btn,
    [data-points-action]
):not(:disabled) {
    cursor: pointer !important;
}

.codes-modal--batch .points-batch-codes-filter--custom {
    position: relative;
    overflow: visible;
    align-items: center;
    padding-right: 8px;
}

.codes-modal--batch .points-batch-codes-select-trigger {
    width: 100%;
    min-width: 0;
    min-height: 32px;
    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 0 4px 0 0;
    appearance: none;
    -webkit-appearance: none;
    border: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    font-weight: 700;
    line-height: 1;
    letter-spacing: 0;
}

.codes-modal--batch .points-batch-codes-select-trigger__value {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.codes-modal--batch .points-batch-codes-select-trigger i {
    flex: 0 0 auto;
    font-size: 0.72rem;
    transition: transform 0.16s ease;
}

.codes-modal--batch .points-batch-codes-filter--custom.is-open .points-batch-codes-select-trigger i {
    transform: rotate(180deg);
}

.codes-modal--batch .points-batch-codes-select-menu {
    position: absolute;
    top: calc(100% + 8px);
    left: 0;
    z-index: 40;
    display: grid;
    gap: 4px;
    width: max(100%, 176px);
    padding: 6px;
    border-radius: 16px;
    border: 1px solid rgba(148, 163, 184, 0.18);
    background: rgba(15, 23, 42, 0.92);
    box-shadow: 0 18px 42px rgba(2, 8, 23, 0.32);
    opacity: 0;
    pointer-events: none;
    transform: translateY(-4px) scale(0.98);
    transform-origin: top left;
    transition: opacity 0.16s ease, transform 0.16s ease, visibility 0.16s ease;
    visibility: hidden;
}

.codes-modal--batch .points-batch-codes-filter--custom.is-open .points-batch-codes-select-menu {
    opacity: 1;
    pointer-events: auto;
    transform: translateY(0) scale(1);
    visibility: visible;
}

.codes-modal--batch .points-batch-codes-select-option {
    min-height: 38px;
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 0 11px;
    border: 1px solid transparent;
    border-radius: 11px;
    background: transparent;
    color: rgba(226, 232, 240, 0.88);
    font: inherit;
    font-weight: 700;
    letter-spacing: 0;
    text-align: left;
}

.codes-modal--batch .points-batch-codes-select-option i {
    width: 14px;
    color: currentColor;
    font-size: 0.78rem;
    opacity: 0;
}

.codes-modal--batch .points-batch-codes-select-option.is-selected i {
    opacity: 1;
}

